@if(!$party->exists && $eligibleParties->isNotEmpty())<script>
document.getElementById('existing-party').addEventListener('change', function () {
    if (!this.value) return;
    const data = JSON.parse(this.selectedOptions[0].dataset.party);
    Object.entries(data).forEach(([key, value]) => { const input = document.querySelector(`[name="party[${key}]"]`); if (input && input.type !== 'hidden') input.value = value ?? ''; });
});
</script>@endif
