@if($role==='supplier')<script>
document.addEventListener('DOMContentLoaded', () => {
    const field = (name) => document.querySelector(`[name="party[${name}]"]`)?.closest('label');
    const rename = (name, label) => { const node = field(name); if (node?.firstChild?.nodeType === Node.TEXT_NODE) node.firstChild.textContent = label; };
    const hide = (name) => { const node = field(name); if (node) node.style.display = 'none'; };
    rename('code', 'Code');
    rename('trading_name', 'Name');
    ['party_kind', 'email', 'ntn', 'sales_tax_registration'].forEach(hide);
    const remarks = document.querySelector('[name="profile[purchase_notes]"]')?.closest('label');
    if (remarks?.firstChild?.nodeType === Node.TEXT_NODE) remarks.firstChild.textContent = 'Remarks';
});
</script>@endif
